"""Read-side queries and JSON shapes for the public API. Every query applies the rolling retention window."""
from collections import defaultdict
from datetime import datetime, timedelta

from sqlalchemy import select
from sqlalchemy.orm import Session, selectinload

from . import countries
from .background import label_for
from .models import Article, Story, StoryBackground
from .timeutil import iso

AI_LABEL = "AI-generated"
AI_DISCLOSURE = (
    "Generated by an AI model from the headlines and short RSS feed excerpts of the articles listed as "
    "sources, not from the full articles. It may be incomplete or wrong; open the original coverage to verify."
)
INSUFFICIENT_PERSPECTIVES = "Insufficient evidence for distinct perspectives"
NO_BACKGROUND = "No background resource available"

AI_MESSAGES = {
    "pending": "AI overview not generated yet. It is created during the next scheduled collection.",
    "failed": "AI overview unavailable: the last generation attempt failed. No text is shown rather than a guess.",
    "outdated": "The previous AI overview cited articles that are no longer in the 7-day window, so it is hidden "
    "until it is regenerated.",
    "updating": "New coverage was added after this overview was generated. It will be refreshed on the next run.",
}


def cutoff_for(now: datetime, retention_hours: int) -> datetime:
    return now - timedelta(hours=retention_hours)


def active_members(session: Session, cutoff: datetime, story_ids: list[str] | None = None) -> dict[str, list[Article]]:
    q = select(Article).where(Article.story_id.is_not(None), Article.published_at >= cutoff)
    if story_ids is not None:
        q = q.where(Article.story_id.in_(story_ids))
    members: dict[str, list[Article]] = defaultdict(list)
    for a in session.scalars(q):
        members[a.story_id].append(a)
    for arts in members.values():
        arts.sort(key=lambda a: (a.published_at, a.id), reverse=True)
    return members


def _publishers(arts: list[Article]) -> list[str]:
    names = []
    for a in arts:
        if a.publisher_name not in names:
            names.append(a.publisher_name)
    return names


def story_list_item(story: Story, arts: list[Article]) -> dict:
    publishers = _publishers(arts)
    return {
        "id": story.id,
        "headline": story.headline,
        "latest_published_at": iso(arts[0].published_at),
        "publisher_count": len(publishers),
        "publishers": publishers,
        "article_count": len(arts),
        "ai_status": story.ai_status,
    }


def list_stories(session: Session, cutoff: datetime, limit: int, offset: int = 0) -> tuple[list[dict], int]:
    members = active_members(session, cutoff)
    stories = session.scalars(select(Story).where(Story.id.in_(list(members)))).all() if members else []
    rows = [(s, members[s.id]) for s in stories]
    rows.sort(key=lambda r: (r[1][0].published_at, r[0].id), reverse=True)
    return [story_list_item(s, arts) for s, arts in rows[offset : offset + limit]], len(rows)


def _article_json(a: Article) -> dict:
    return {
        "id": a.id,
        "title": a.title,
        "publisher_id": a.publisher_id,
        "publisher_name": a.publisher_name,
        "url": a.url,
        "excerpt": a.excerpt,
        "published_at": iso(a.published_at),
        "date_estimated": a.date_estimated,
    }


def _source_refs(ids: list[str], by_id: dict[str, Article]) -> list[dict]:
    return [
        {"article_id": i, "publisher_name": by_id[i].publisher_name, "title": by_id[i].title, "url": by_id[i].url}
        for i in ids
        if i in by_id
    ]


def summary_status(story: Story, active_ids: set[str]) -> str:
    s = story.summary
    if s is None:
        return "failed" if story.ai_status == "failed" else "pending"
    cited = set(s.article_ids or []) | set(s.overview_sources or [])
    for p in s.perspectives or []:
        cited |= set(p.get("sources") or [])
    if not cited <= active_ids:
        return "outdated"
    if s.input_hash != story.input_hash:
        return "updating"
    return "ok"


def ai_json(story: Story, arts: list[Article]) -> dict:
    by_id = {a.id: a for a in arts}
    status = summary_status(story, set(by_id))
    out = {
        "status": status,
        "label": AI_LABEL,
        "disclosure": AI_DISCLOSURE,
        "message": AI_MESSAGES.get(status),
        "generated_at": None,
        "model": None,
        "prompt_version": None,
        "overview": None,
        "agreement": None,
        "disagreement_or_uncertainty": None,
        "overview_sources": [],
        "perspectives_status": None,
        "perspectives": [],
        "perspectives_message": None,
    }
    s = story.summary
    if s is None or status == "outdated":
        return out
    out.update(
        generated_at=iso(s.generated_at),
        model=s.model,
        prompt_version=s.prompt_version,
        overview=s.overview,
        agreement=s.agreement,
        disagreement_or_uncertainty=s.disagreement_or_uncertainty,
        overview_sources=_source_refs(s.overview_sources or [], by_id),
        perspectives_status=s.perspectives_status,
        perspectives=[
            {
                "label": p["label"],
                "summary": p["summary"],
                "evidence_limits": p.get("evidence_limits", ""),
                "sources": _source_refs(p.get("sources") or [], by_id),
            }
            for p in (s.perspectives or [])
        ],
        perspectives_message=INSUFFICIENT_PERSPECTIVES if s.perspectives_status != "supported" else None,
    )
    return out


def background_json(story: Story) -> dict:
    resources = [
        {
            "title": link.resource.title,
            "url": link.resource.url,
            "description": link.resource.description,
            "source": link.resource.source,
            "entity": link.entity,
            "label": label_for(link.resource.title, link.resource.description, link.resource.source),
        }
        for link in story.background_links
    ]
    return {
        "status": story.background_status,
        "resources": resources,
        "message": None if resources else NO_BACKGROUND,
    }


def story_detail(session: Session, story_id: str, cutoff: datetime) -> dict | None:
    story = session.scalars(
        select(Story)
        .where(Story.id == story_id)
        .options(
            selectinload(Story.summary),
            selectinload(Story.background_links).selectinload(StoryBackground.resource),
        )
    ).one_or_none()
    if story is None:
        return None
    arts = active_members(session, cutoff, [story_id]).get(story_id)
    if not arts:
        return None  # every article has left the window; the story is no longer served
    return {
        **story_list_item(story, arts),
        "articles": [_article_json(a) for a in arts],
        "background": background_json(story),
        "ai": ai_json(story, arts),
    }


def live_stories_for_country(session: Session, code: str, cutoff: datetime, limit: int = 5) -> list[dict]:
    """Current grouped stories whose headlines or excerpts mention the country."""
    members = active_members(session, cutoff)
    scored = []
    for sid, arts in members.items():
        hits = sum(1 for a in arts if countries.mentions(f"{a.title}\n{a.excerpt}", code))
        if hits:
            scored.append((hits / len(arts) >= 0.5, len(_publishers(arts)), arts[0].published_at, sid))
    scored.sort(reverse=True)
    top = scored[:limit]
    stories = {s.id: s for s in session.scalars(select(Story).where(Story.id.in_([t[3] for t in top])))}
    return [story_list_item(stories[t[3]], members[t[3]]) for t in top if t[3] in stories]
